css:
.button {
  cursor: pointer;
  position: relative;
  padding: 16px 40px;
  font-size: 18px;
  color: white;
  background: #0f0f1a;
  border: none;
  border-radius: 14px;
  overflow: hidden;
  z-index: 1;
  letter-spacing: 1px;
  transition: transform 0.2s ease;
}

.button::before {
  content: "";
  position: absolute;
  inset: -3px;
  background: conic-gradient(
    from 0deg,
    #ff00cc,
    #3333ff,
    #00ffee,
    #ffcc00,
    #ff00cc
  );
  border-radius: 16px;
  animation: spin 4s linear infinite;
  z-index: -2;
  filter: blur(8px);
}

.button::after {
  content: "";
  position: absolute;
  inset: 2px;
  background: #0f0f1a;
  border-radius: 12px;
  z-index: -1;
}

.button:hover::before {
  animation-duration: 1s;
  filter: blur(12px) brightness(1.5);
}

.button:active {
  transform: scale(0.9) skewX(6deg);
  filter: hue-rotate(120deg);
}

@keyframes spin {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
